          bagian.push(`${k}: ${rupiah(Number(v))}`);
        } else {
          bagian.push(`${k}: ${String(v).trim()}`);
        }
      }
    }
    if (bagian.length) teks.push('- ' + bagian.join(' | '));
  }
  return teks.length ? teks.join('\n') : '(kosong)';
}

