const SERAH = 'Mulai dari sini Kakak akan dibalas langsung oleh admin kami, bukan asisten AI.';
const SAMBIL = 'Sambil menunggu, kalau ada pertanyaan lain soal harga, jadwal, atau promo, Kakak tetap bisa tanya saya ya.';
// Saklar jawab_saat_menunggu_admin di node Pengaturan (penjelasan lengkap di node Tentukan Jalur).
const modeMenunggu = String(cfg.jawab_saat_menunggu_admin ?? '').trim().toLowerCase();
const jawabSaatMenunggu = modeMenunggu === 'selalu' || (modeMenunggu === 'luar_jam' && Boolean(chat.luar_jam));
function penutupSerah() {
  return jawabSaatMenunggu ? `${kapanDibalas()} ${SAMBIL}` : `${SERAH} ${kapanDibalas()}`;
}
const teksTerusan = {
  harga_tidak_ada: `Untuk yang itu saya belum punya harga pastinya, Kak, jadi saya tidak mau asal sebut. Saya teruskan ke admin kami ya. ${penutupSerah()}`,
  kondisi_kulit: `Untuk kondisi kulit, saya tidak memberi saran supaya tidak keliru. Pertanyaan Kakak saya teruskan ke admin kami agar dijawab langsung oleh tim klinik. ${penutupSerah()}`,
  booking: `Baik ${booking && booking.nama ? 'Kak ' + booking.nama : sapa}, permintaan booking ${booking && booking.perawatan ? booking.perawatan : 'perawatan'}${booking && booking.waktu ? ' untuk ' + booking.waktu : ''} sudah saya catat dan saya teruskan ke admin. Jadwalnya belum pasti sampai admin mengonfirmasi. ${penutupSerah()}`,
  minta_admin: `Baik Kak, saya sambungkan ke admin kami. ${penutupSerah()}`,
  komplain: `Mohon maaf atas ketidaknyamanannya, Kak. Saya teruskan ke admin kami supaya segera ditangani. ${penutupSerah()}`,
  lainnya: `Untuk yang itu saya teruskan ke admin kami ya, Kak, supaya jawabannya tepat. ${penutupSerah()}`,
};
let pesan_pasien = tindakan === 'teruskan' ? teksTerusan[alasan] : balasan;
if (tindakan === 'teruskan' && setuju && alasan !== 'booking') {
  pesan_pasien = `Baik Kak, saya teruskan ke tim klinik ya. ${penutupSerah()}`;
}

// 5. Di pesan pertama, bot memperkenalkan diri sebagai asisten AI.
//    Kalau jawaban sudah diawali sapaan ("Halo Kak Rina, ..." atau "Baik Kak Rina, ..."),
//    sapaan itu dipakai sekali saja supaya tidak dobel.
function perkenalan(teks, kalimat) {
  const m = teks.match(/^(halo|hallo|hai|hi|selamat (?:pagi|siang|sore|malam)|baik)(?:\s+juga)?\s*,?\s*(kak(?:ak)?(?:\s+[^\s,.!?]+){0,2})?\s*[,.!]\s*/i);
  if (!m) return `Halo ${sapa}, ${kalimat} ` + teks;
  const sebutan = m[2] && /\s/.test(m[2].trim())
    ? 'Kak ' + m[2].trim().split(/\s+/).slice(1).join(' ')
    : sapa;
  let sisa = teks.slice(m[0].length);
  if (/^baik$/i.test(m[1])) sisa = 'Baik, ' + sisa;
  else sisa = sisa.charAt(0).toUpperCase() + sisa.slice(1);
  return `Halo ${sebutan}, ${kalimat} ${sisa}`;
}
const pesanPertama = (chat.riwayat || []).length === 0;
if (pesanPertama && !/(saya|ini) asisten (AI|otomatis)/i.test(pesan_pasien)) {
  pesan_pasien = perkenalan(pesan_pasien, `saya asisten AI ${cfg.nama_klinik}.`);
}
// 5b. Kalau bot baru aktif lagi setelah chat ini ditangani admin, beri tahu pasien bahwa yang membalas asisten AI.
else if (chat.kembali_aktif && !/(saya|ini) asisten (AI|otomatis)/i.test(pesan_pasien)) {
  pesan_pasien = perkenalan(pesan_pasien, `ini asisten AI ${cfg.nama_klinik} lagi.`);
}

// 6. Pemberitahuan untuk admin kalau diteruskan.
const judul = {
  harga_tidak_ada: 'Perlu ditangani: harga tidak ada di daftar',
  kondisi_kulit: 'Perlu ditangani: pertanyaan kondisi kulit',
  booking: 'Permintaan booking, mohon dikonfirmasi',
  minta_admin: 'Perlu ditangani: pasien minta bicara dengan admin',
  komplain: 'Perlu ditangani: komplain',
  lainnya: 'Perlu ditangani',
};
let pesan_admin = '';
// Pesan pertama hari ini dari pasien yang masih menunggu admin: admin diingatkan sekali.
if (tindakan === 'jawab' && chat.menunggu_admin && chat.admin_tambahan) pesan_admin = chat.admin_tambahan;
if (tindakan === 'teruskan') {
  const baris = [`[${judul[alasan]}]`, `Dari: ${chat.nama || 'tanpa nama'} (${chat.nomor})`];
  if (alasan === 'booking' && booking) {
    baris.push(`Nama: ${booking.nama || '-'}`, `Perawatan: ${booking.perawatan || '-'}`, `Waktu diminta: ${booking.waktu || '-'}`);
  }
  if (setuju) {
    const konteks = (chat.riwayat || []).slice(-4)
      .map(r => `${r.arah === 'masuk' ? 'Pasien' : 'Bot'}: ${String(r.pesan || '').slice(0, 200)}`);
    if (konteks.length) baris.push('Percakapan sebelumnya:', ...konteks);
  }
  baris.push(`Pesan: "${chat.pesan}"`);
  if (catatan) baris.push(`Catatan sistem: ${catatan}`);
  pesan_admin = baris.join('\n');
}

return [{ json: {
  perlu_ai: true, nomor: chat.nomor, nama: chat.nama,
  pesan_pasien, pesan_admin,
  log: { tindakan, alasan, topik, booking, perawatan },
  catatan_sistem: catatan,
} }];

// Mengubah keputusan menjadi daftar pesan WhatsApp: satu untuk pasien, satu untuk admin.
const cfg = $('Pengaturan').first().json;
const k = $input.first().json;

const adminRapi = String(cfg.nomor_admin ?? '').replace(/\D/g, '');
const kiriman = [];
if (k.pesan_pasien) kiriman.push({ jenis: 'pasien', target: k.nomor, message: k.pesan_pasien });
if (k.pesan_admin && adminRapi.length >= 9) kiriman.push({ jenis: 'admin', target: adminRapi, message: k.pesan_admin });

const dasar = {
  nomor: k.nomor,
  pesan_pasien: k.pesan_pasien || '',
  log: k.log,
  ada_kiriman: kiriman.length > 0,
};
if (kiriman.length === 0) return [{ json: { ...dasar, jenis: '', target: '', message: '' } }];
return kiriman.map(x => ({ json: { ...dasar, ...x } }));

// Menyiapkan satu baris catatan untuk Supabase: apa yang dilakukan bot terhadap chat ini.
const kiriman = $('Susun Kiriman').all().map(i => i.json);
const k = kiriman[0];

// Balasan dianggap terkirim kalau Fonnte tidak melaporkan gagal untuk pesan ke pasien.
let terkirim = false;
if (k.ada_kiriman && $('Kirim WhatsApp').isExecuted) {
  const hasil = $('Kirim WhatsApp').all().map(i => i.json);
  const urutanPasien = kiriman.findIndex(x => x.jenis === 'pasien');
  if (urutanPasien !== -1) {
    const h = hasil[urutanPasien] || {};
    terkirim = !h.error && h.status !== false && h.status !== 'false';
  }
}

return [{ json: {
  p_nomor: k.nomor,
  p_pesan_pasien: k.pesan_pasien || null,
  p_tindakan: k.log.tindakan,
  p_alasan: k.log.alasan,
  p_topik: k.log.topik,
  p_booking: k.log.booking,
  p_terkirim: terkirim,
} }];

// Menyiapkan satu baris untuk sheet Prospek & Booking.
// Aturan: bot hanya MEMAJUKAN status (Tanya-tanya -> Menunggu Konfirmasi).
// Status Batal dan Terkonfirmasi yang diisi admin tidak ditimpa, kecuali pasien Batal mengajukan booking baru.
const chat = $('Cek Pasien Lama').first().json;
const kiriman = $('Susun Kiriman').first().json;
const baris = $('Baca Prospek').all().map(i => i.json);

// Kalau sheet gagal dibaca, jangan menulis apa pun supaya tidak muncul baris ganda.
if (baris.some(b => b && b.error)) return [];

function nomorRapi(n) {
  let d = String(n ?? '').replace(/\D/g, '');
  if (d.startsWith('0')) d = '62' + d.slice(1);
  else if (d.startsWith('8')) d = '62' + d;
  return d;
}
function teks(v) {
  const t = String(v ?? '').trim();
  return /^(null|undefined|-)$/i.test(t) ? '' : t;
}

const sekarang = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false,
}).format(new Date());

// Label dihitung oleh Google Sheets sendiri, jadi ikut berubah walau workflow tidak berjalan.
const LABEL = '=IF(INDIRECT("E"&ROW())<>"Menunggu Konfirmasi","",IF(INDIRECT("H"&ROW())="","",IF(NOW()-INDIRECT("H"&ROW())>1,"⚠️ Lewat 24 jam","")))';

const ada = baris.find(b => b && b['Nomor WA'] && nomorRapi(b['Nomor WA']) === chat.nomor);
const statusSekarang = ada ? teks(ada.Status) : '';
const log = kiriman.log || {};
const booking = log.booking || {};
const minta = log.tindakan === 'teruskan' && log.alasan === 'booking';
const perawatan = teks(log.perawatan) || teks(booking.perawatan);
const pesan = (chat.pesan || (chat.media ? '(mengirim foto atau berkas)' : '')).slice(0, 300);

// Pasien lama (nomornya sudah ada di sheet Booking): tidak ditambahkan sebagai prospek baru.
// Kalau sebelumnya prospek, statusnya otomatis menjadi Terkonfirmasi.
if (chat.pasien_lama) {
  if (!ada) return [];
  const out = { 'Nomor WA': chat.nomor, 'Terakhir Chat': sekarang, 'Pesan Terakhir': pesan };
  if (['', 'Tanya-tanya', 'Menunggu Konfirmasi'].includes(statusSekarang)) out['Status'] = 'Terkonfirmasi';
  return [{ json: out }];
}

const out = { 'Nomor WA': chat.nomor, 'Terakhir Chat': sekarang, 'Pesan Terakhir': pesan, 'Label': LABEL };
const namaBooking = teks(booking.nama);
const namaChat = teks(chat.nama_di_sheet) || teks(chat.nama);

if (!ada) {
  out['Nama'] = namaBooking || namaChat;
  out['Pertama Chat'] = sekarang;
  out['Perawatan'] = perawatan;
  out['Status'] = minta ? 'Menunggu Konfirmasi' : 'Tanya-tanya';
  if (minta) {
    out['Waktu Diminta'] = teks(booking.waktu);
    out['Diteruskan Pada'] = sekarang;
  }
  return [{ json: out }];
}

if (namaBooking) out['Nama'] = namaBooking;
else if (!teks(ada.Nama) && namaChat) out['Nama'] = namaChat;
if (perawatan) out['Perawatan'] = perawatan;

if (minta && statusSekarang !== 'Terkonfirmasi') {
  if (teks(booking.waktu)) out['Waktu Diminta'] = teks(booking.waktu);
  if (statusSekarang !== 'Menunggu Konfirmasi' || !teks(ada['Diteruskan Pada'])) {
    // Permintaan baru (termasuk dari pasien yang sebelumnya Batal): jam tunggu dimulai dari sekarang.
    out['Status'] = 'Menunggu Konfirmasi';
    out['Diteruskan Pada'] = sekarang;
  }
  // Kalau sudah Menunggu Konfirmasi, jam tunggu tidak di-reset supaya permintaan lama tetap terlihat menggantung.
} else if (!statusSekarang) {
  out['Status'] = 'Tanya-tanya';
}

return [{ json: out }];

// Sapaan kilat: pesan PERTAMA yang isinya hanya sapaan ("halo kak", "permisi, mau tanya-tanya perawatan wajah")
// langsung dibalas dengan kalimat jadi dari Pengaturan (isi_sapaan_kilat), tanpa menunggu bubble berikutnya
// dan tanpa bertanya ke AI. Pesan lain lanjut ke jalur biasa (Tunggu Pasien Selesai).
const cfg = $('Pengaturan').first().json;
const chat = $('Cek Pasien Lama').first().json;
const status = $('Catat Chat Masuk').first().json;
const isi = String(cfg.isi_sapaan_kilat ?? '').trim();

// Kata yang boleh ada di sapaan. Huruf berulang dirapikan dulu ("haloo" -> "halo", "assalamualaikum" -> "asalamualaikum").
const SAPA = ['halo', 'helo', 'hai', 'hay', 'hi', 'hy', 'hey', 'pagi', 'siang', 'sore', 'malam', 'permisi',
  'asalamualaikum', 'asalamu', 'salam', 'kak', 'kakak', 'min', 'admin', 'mimin', 'mba', 'mbak', 'sis', 'sist',
  'gan', 'dok', 'tanya', 'nanya', 'bertanya', 'info', 'informasi'];
const PELENGKAP = ['selamat', 'alaikum', 'wr', 'wb', 'warahmatulahi', 'wabarakatuh', 'ka', 'mas', 'bu', 'ibu', 'pak',
  'mau', 'ingin', 'pengen', 'pingin', 'pengin', 'boleh', 'bisa', 'saya', 'aku', 'sy', 'aq', 'dong', 'donk', 'ya', 'yah',
  'nih', 'dulu', 'sedikit', 'dikit', 'seputar', 'soal', 'tentang', 'mengenai', 'perawatan', 'treatment', 'wajah',
  'muka', 'kulit', 'klinik', 'di', 'sini', 'disini', 'ini', 'mohon', 'minta', 'numpang', 'kah', 'nya'];
const BOLEH = new Set([...SAPA, ...PELENGKAP]);
const WAJIB = new Set(SAPA);

function hanyaSapaan(teks) {
  const kata = String(teks ?? '').toLowerCase()
    .replace(/[^a-z\s]/g, ' ')
    .split(/\s+/).filter(Boolean)
    .map(k => k.replace(/(.)\1+/g, '$1'));
  if (kata.length === 0 || kata.length > 12) return false;
  return kata.every(k => BOLEH.has(k)) && kata.some(k => WAJIB.has(k));
}

const kilat = isi !== ''
  && !chat.pasien_lama
  && !chat.media
  && !status.duplikat
  && (status.riwayat || []).length === 0
  && !(cfg.jawab_hanya_di_luar_jam === true && !chat.luar_jam)
  && Number(status.balasan_bot_bulan_ini || 0) < Number(cfg.batas_balasan_per_bulan || Infinity)
  && hanyaSapaan(chat.pesan);

if (!kilat) return [{ json: { kilat: false } }];

const sapaNama = chat.nama ? `Kak ${String(chat.nama).trim().split(/\s+/)[0]}` : 'Kak';
return [{ json: {
  kilat: true,
  perlu_ai: false,
  nomor: chat.nomor,
  nama: chat.nama,
  pesan_pasien: `Halo ${sapaNama}, saya asisten AI ${cfg.nama_klinik}. ${isi}`,
  pesan_admin: '',
  log: { tindakan: 'jawab', alasan: 'sapaan_kilat', topik: 'lainnya', booking: null },
} }];

// Membaca salinan Data Klinik dari data table "Salinan Data Klinik" (diisi workflow Klinik - Perbarui Salinan Data).
// ada = true kalau keempat tab tersedia dan salinannya belum lebih dari 6 jam. Kalau false, workflow membaca Google Sheets langsung.
const baris = $input.all().map(i => i.json).filter(r => r && r.tab);
const out = { ada: false };
let tertua = Infinity;
for (const r of baris) {
  try {
    const isi = JSON.parse(r.isi || '[]');
    if (Array.isArray(isi)) out[r.tab] = isi;
  } catch (e) {
    // baris rusak diabaikan
  }
  const t = Date.parse(r.diperbarui);
  if (Number.isFinite(t)) tertua = Math.min(tertua, t);
}
const lengkap = Array.isArray(out.harga) && out.harga.length > 0
  && ['jadwal', 'promo', 'info'].every(t => Array.isArray(out[t]));
const segar = Number.isFinite(tertua) && Date.now() - tertua < 6 * 3600000;
out.ada = lengkap && segar;
out.diperbarui = Number.isFinite(tertua) ? new Date(tertua).toISOString() : '';
return [{ json: out }];
